<?php

namespace Tests\Support;

use Illuminate\Http\UploadedFile;

final class MinimalTestImage
{
    public static function jpeg(string $filename = 'test.jpg'): UploadedFile
    {
        return UploadedFile::fake()->createWithContent(
            $filename,
            base64_decode(
                '',
                true,
            ) ?: '',
        );
    }
}
